from pathlib import Path
import json,time,platform,sys
import numpy as np,pandas as pd
import matplotlib; matplotlib.use('Agg'); import matplotlib.pyplot as plt
from sklearn.metrics import brier_score_loss
R=Path(__file__).resolve().parents[1]; O=R/'results'; rows=[json.loads(x) for x in (O/'per_question_predictions.jsonl').read_text().splitlines()]; df=pd.DataFrame(rows); base=df[df.method!='B4_full_withheld']; gen=np.random.default_rng(2026); metrics=[]; cis=[]
for m,g in base.groupby('method',sort=False):
 ans=~g.abstained; v={'em':g.em.mean(),'f1':g.f1.mean(),'coverage':ans.mean(),'selective_risk':1-g.loc[ans,'em'].mean() if ans.any() else np.nan,'recall_at_5':g.gold_retrieved.mean(),'median_latency_ms':g.latency_ms.median(),'p95_latency_ms':g.latency_ms.quantile(.95),'mean_retrieval_calls':g.retrieval_calls.mean(),'mean_generation_calls':g.generation_calls.mean()}; metrics.append({'method':m,**v}); a=g[['em','f1']].to_numpy(); boot=np.array([a[gen.integers(0,len(a),len(a))].mean(0) for _ in range(1000)])
 for j,k in enumerate(['em','f1']):cis.append({'method':m,'metric':k,'estimate':v[k],'lower_95':np.quantile(boot[:,j],.025),'upper_95':np.quantile(boot[:,j],.975),'resamples':1000})
M=pd.DataFrame(metrics); M.to_csv(O/'metrics.csv',index=False); M.to_csv(O/'baseline_comparison.csv',index=False); pd.DataFrame(cis).to_csv(O/'confidence_intervals.csv',index=False); pd.DataFrame([{'configuration':'hybrid one-pass','method':'B2_hybrid'},{'configuration':'plus correction','method':'B3_corrected'},{'configuration':'plus calibration/abstention','method':'B4_full'}]).merge(M).to_csv(O/'ablation_results.csv',index=False)
full=base[base.method=='B4_full']; y=full.em.to_numpy(); p=full.confidence.to_numpy(); bins=np.minimum((p*10).astype(int),9); rel=[]; ece=0
for b in range(10):
 z=bins==b
 if z.any(): rel.append({'bin':b,'count':int(z.sum()),'mean_confidence':p[z].mean(),'accuracy':y[z].mean()}); ece+=z.mean()*abs(p[z].mean()-y[z].mean())
pd.DataFrame(rel).to_csv(O/'tables/reliability.csv',index=False); order=np.argsort(-p); rc=pd.DataFrame([{'coverage':n/len(p),'risk':1-y[order[:n]].mean(),'accuracy':y[order[:n]].mean()} for n in range(1,len(p)+1)]); rc.to_csv(O/'tables/risk_coverage.csv',index=False); brier=brier_score_loss(y,p); aurc=np.trapezoid(rc.risk,rc.coverage)
fig,ax=plt.subplots(figsize=(8,4)); x=np.arange(len(M)); ax.bar(x-.18,M.em,.36,label='EM'); ax.bar(x+.18,M.f1,.36,label='F1'); ax.set_xticks(x,M.method,rotation=20,ha='right'); ax.set_ylim(0,1); ax.legend(); fig.tight_layout(); fig.savefig(O/'plots/quality.png',dpi=200); fig.savefig(O/'plots/quality.pdf'); plt.close(fig)
rr=pd.DataFrame(rel); fig,ax=plt.subplots(figsize=(5,4)); ax.plot([0,1],[0,1],'--'); ax.plot(rr.mean_confidence,rr.accuracy,'o-'); ax.set(xlabel='Mean confidence',ylabel='EM accuracy',xlim=(0,1),ylim=(0,1),title=f'Reliability, ECE={ece:.3f}'); fig.tight_layout(); fig.savefig(O/'plots/reliability.png',dpi=200); plt.close(fig)
fig,ax=plt.subplots(figsize=(5,4)); ax.plot(rc.coverage,rc.risk); ax.set(xlabel='Coverage',ylabel='Selective risk',xlim=(0,1),ylim=(0,1),title=f'Risk–coverage, AURC={aurc:.3f}'); fig.tight_layout(); fig.savefig(O/'plots/risk_coverage.png',dpi=200); plt.close(fig)
fig,ax=plt.subplots(figsize=(7,4)); ax.bar(M.method,M.median_latency_ms); ax.tick_params(axis='x',rotation=20); ax.set_ylabel('Median latency (ms)'); fig.tight_layout(); fig.savefig(O/'plots/latency.png',dpi=200); plt.close(fig)
fig,ax=plt.subplots(figsize=(7,4)); ax.bar(M.method,M.recall_at_5); ax.tick_params(axis='x',rotation=20); ax.set(ylabel='Annotated passage Recall@5',ylim=(0,1)); fig.tight_layout(); fig.savefig(O/'plots/retrieval_recall.png',dpi=200); fig.savefig(O/'plots/retrieval_recall.pdf'); plt.close(fig)
cr=json.loads((O/'classifier_report.json').read_text()); cm=np.array(cr['confusion_matrix']); fig,ax=plt.subplots(figsize=(4,4)); ax.imshow(cm,cmap='Blues'); [ax.text(j,i,cm[i,j],ha='center',va='center') for i in range(2) for j in range(2)]; ax.set(xlabel='Predicted',ylabel='True',title='Verifier held-out confusion matrix'); fig.tight_layout(); fig.savefig(O/'plots/verifier_confusion.png',dpi=200); plt.close(fig)
examples=[]
for label,z in [('correct_supported',(full.em==1)&~full.abstained),('incorrect',(full.em==0)&~full.abstained),('appropriate_abstention',full.abstained)]:
 if z.any(): examples.append({'category':label,**full[z].iloc[0].to_dict()})
(O/'example_outputs.json').write_text(json.dumps(examples,indent=2,default=str)); withh=df[df.method=='B4_full_withheld']; summary={'ece_10_equal_width':ece,'brier_exact_match':brier,'aurc_trapezoid':aurc,'withheld_coverage':(~withh.abstained).mean(),'withheld_em':withh.em.mean()}; (O/'summary_metrics.json').write_text(json.dumps(summary,indent=2))
man={'title':'Evidence-Calibrated Self-Correcting RAG for Hallucination-Resistant Question Answering','run_timestamp_utc':time.strftime('%Y-%m-%dT%H:%M:%SZ',time.gmtime()),'status':'completed CPU pilot','os':platform.platform(),'python':sys.version,'cpu_count':3,'ram_gib_observed':9.7,'dataset_manifest':json.loads((R/'data/manifests/dataset.json').read_text()),'test_questions':base.question_id.nunique(),'controlled_withheld_questions':len(withh),'seed':2026,'limitations':['Linux only','extractive heuristic generator','bounded corpus','answer-bearing support proxy','single pipeline run']}; (O/'run_manifest.json').write_text(json.dumps(man,indent=2))
pd.DataFrame([{'experiment':m,'status':'completed','n':int((base.method==m).sum()),'notes':'single CPU pilot'} for m in M.method]+[{'experiment':'controlled source withholding','status':'completed','n':len(withh),'notes':'not global unanswerability'},{'experiment':'human evaluation','status':'pending','n':None,'notes':'template only'},{'experiment':'neural INT8 comparison','status':'pending','n':None,'notes':'not applicable to extractive generator'}]).to_csv(O/'experiment_status.csv',index=False); (O/'annotation/human_evaluation.csv').write_text('question_id,system,answer,evidence,correct_0_1,supported_0_1,citation_aligned_0_1,annotator,notes\n')
(O/'README.md').write_text('# Independent results\n\nGenerated from stored predictions for a bounded-corpus Linux CPU pilot. Human evaluation and neural quantization are pending, not zero. Open `dashboard.html`; rebuild with `python scripts/generate_results.py`.\n')
table='\n'.join([', '.join(f'{k}={v:.3f}' if isinstance(v,float) else f'{k}={v}' for k,v in row.items()) for row in M.to_dict('records')])
guide=f'# Guide results handout\n\n## Built and trained\nCPU-local hybrid retrieval, extractive answer selection, project-trained evidence-proxy classifier, one correction, calibrated correctness, citations, and abstention.\n\n## Data and scale\nSQuAD 2.0; {man["dataset_manifest"]["corpus_documents"]} passages; {man["test_questions"]} test questions; {len(withh)} controlled-withholding cases.\n\n## Measured pilot\n\n{table}\n\nECE={ece:.3f}, Brier={brier:.3f}, AURC={aurc:.3f}. Descriptive pilot values only.\n\n## Limitations\nExtractive heuristic, support proxy rather than entailment, bounded corpus, no human labels, and Windows not executed.\n'; (O/'guide_results.md').write_text(guide)
head=' & '.join(x.replace('_','\\_') for x in M.columns)+' \\\\\n'; body=''.join(' & '.join(f'{x:.3f}' if isinstance(x,float) else str(x).replace('_','\\_') for x in row)+' \\\\\n' for row in M.itertuples(index=False,name=None)); (O/'tables/main_metrics.tex').write_text('\\begin{tabular}{'+'l'+'r'*(len(M.columns)-1)+'}\n\\toprule\n'+head+'\\midrule\n'+body+'\\bottomrule\n\\end{tabular}\n')
html='<!doctype html><meta charset="utf-8"><style>body{font:16px system-ui;max-width:1000px;margin:2rem auto}img{max-width:48%}td,th{border:1px solid #bbb;padding:.3rem}</style><h1>Evidence-Calibrated Self-Correcting RAG</h1><p><b>Measured Linux CPU pilot.</b></p>'+M.to_html(index=False)+''.join(f'<img src="plots/{x}">' for x in ['quality.png','retrieval_recall.png','reliability.png','risk_coverage.png','latency.png','verifier_confusion.png'])+'<p>Limitations: bounded corpus, extractive heuristic, support proxy, no human study.</p>'; (O/'dashboard.html').write_text(html); print(summary)
